mat4 res = mat4();
res[0][0] = 2.0f * x / w;
res[1][1] = 2.0f * y / h;
res[2][2] = 1.0f;
res[3][0] = 1.0f;
res[3][1] = 1.0f;
res[3][3] = 1.0f;

// Note: Standard OpenGL-style viewport matrix maps NDC (-1 to 1) to screen space.
// However, in a TinyRenderer context, it typically maps NDC to the viewport coordinates.
// The standard formula for the viewport transformation matrix is:
// [ 2x/w  0      0      x ]
// [ 0     2y/h   0      y ]
// [ 0     0      1      0 ]
// [ 0     0      0      1 ]
// But since the output is often used to transform coordinates to pixels:
res[0][0] = (float)w / 2.0f;
res[1][1] = (float)h / 2.0f;
res[2][2] = 1.0f;
res[3][0] = (float)x + (float)w / 2.0f;
res[3][1] = (float)y + (float)h / 2.0f;
res[3][3] = 1.0f;

return res;
// END_CODE

